'use strict';

// MAIN //

/**
* Returns a list of 20 colors as RGB hexadecimal strings for use as a categorical scheme.
*
* @returns {Array<string>} list of colors
*
* @example
* var list = category20c();
* // returns [...]
*/
function category20c() {
	return [
		'#3182bd',
		'#6baed6',
		'#9ecae1',
		'#c6dbef',
		'#e6550d',
		'#fd8d3c',
		'#fdae6b',
		'#fdd0a2',
		'#31a354',
		'#74c476',
		'#a1d99b',
		'#c7e9c0',
		'#756bb1',
		'#9e9ac8',
		'#bcbddc',
		'#dadaeb',
		'#636363',
		'#969696',
		'#bdbdbd',
		'#d9d9d9'
	];
}


// EXPORTS //

module.exports = category20c;
